import {stages,resources} from './data.js';
import {lessons} from './curriculum-data.js';
import {studyGuides,engineeringHabits,projects,fieldManualSources} from './field-manual-data.js';
import {capabilityPaths,launchPrinciples,collegeLinks} from './platform-data.js';
import {concepts,missions} from './concepts-data.js';
import {historyEntries} from './history-data.js';
import {skills,getDrillReview} from './drill-engine.js';
import {parseBackup,mergeWorkspace,downloadBackup} from './workspace.js';

const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,text)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(text)} ↗</a>`;
const intro=(tag,title,text)=>`<header class="page-intro"><div class="eyebrow">${e(tag)}</div><h1>${title}</h1><p>${e(text)}</p></header>`;
const paras=items=>items.map(p=>`<p>${e(p)}</p>`).join('');
const sourceLinks=items=>`<div class="source-links">${items.map(s=>link(s.url,s.title)).join('')}</div>`;
const stageName=id=>stages.find(s=>s.id===id)?.title||id;
const number=n=>String(n).padStart(2,'0');
const stageTabs=(route,selected)=>`<div class="stage-tabs" aria-label="Filter by stage"><a href="#${route}" class="${!selected?'active':''}" ${!selected?'aria-current="page"':''}>All stages</a>${stages.map(s=>`<a href="#${route}/${s.id}" class="${selected===s.id?'active':''}" ${selected===s.id?'aria-current="page"':''}>${e(s.title)}</a>`).join('')}</div>`;
const countRead=(state,key,items)=>items.filter(x=>state[key]?.[x.id]?.read).length;
const noteLink=(title)=>`<a class="text-link" href="#notebook/${encodeURIComponent(title)}">Keep a reflection →</a>`;
const lessonLink=l=>`#lesson/${l.id}`;
const readTools=()=>`<div class="reader-tools"><button class="text-link" data-reading>Change text size</button><button class="text-link" data-print>Print this page</button></div>`;
const sectionHead=(tag,title,desc='')=>`<div class="section-head"><div><div class="eyebrow">${e(tag)}</div><h2>${title}</h2></div>${desc?`<p>${e(desc)}</p>`:''}</div>`;

export function platformHome(state){
 const next=lessons.find(l=>l.id===state.lastLesson)||lessons.find(l=>!state.lessons?.[l.id]?.read)||lessons[0];
 const reviews=getDrillReview(state.drills),due=reviews.filter(r=>r.due).length;
 return `<section class="launch-hero"><img class="launch-photo" src="/math_prep/media/cupola-earth.webp" alt="Earth seen through the windows of the International Space Station Cupola" fetchpriority="high" width="1600" height="1065"><div class="launch-shade"></div><div class="launch-copy"><div class="eyebrow"><span class="status-dot"></span> YOUR ENGINEERING FOUNDATION</div><h1>Extraordinary things.<br><em>Ordinary beginnings.</em></h1><p>Spacecraft, robots, and places to live beyond Earth begin with people who can reason carefully. Start with one number, one relationship, one problem you can explain.</p><div class="actions"><a class="btn gold" href="${lessonLink(next)}">${state.lastLesson?'Continue learning':'Begin the curriculum'} →</a><a class="hero-text-link" href="#diagnostic">Find a useful starting point</a></div><div class="hero-footnote"><span>ARITHMETIC → PRECALCULUS</span><span>BUILT FOR A FUTURE IN AEROSPACE</span></div></div><div class="photo-caption">THE HORIZON IS REAL. SO IS THE WORK.<br>${link('https://www.nasa.gov/international-space-station/cupola/','ISS Cupola · Image: NASA')}</div></section>
 <div class="platform-inventory"><a href="#curriculum"><b>${lessons.length}</b><span>guided lessons</span></a><a href="#drills"><b>${skills.length}</b><span>fresh practice skills</span></a><a href="#study"><b>${studyGuides.length}</b><span>study field notes</span></a><a href="#projects"><b>${projects.length}</b><span>small engineering projects</span></a></div>
 <section class="continue-strip"><div><div class="eyebrow">YOUR NEXT USEFUL STEP</div><h2>${e(next.title)}</h2><p>${e(next.subtitle)}</p><a href="${lessonLink(next)}" class="text-link">Open lesson →</a></div><div class="continue-stats"><a href="#progress"><b>${countRead(state,'lessons',lessons)}<small> / ${lessons.length}</small></b><span>lessons marked read</span></a><a href="#review"><b>${due}</b><span>skills due for a revisit</span></a><small>Personal records in this browser. Reading is not a mastery score.</small></div></section>
 <section class="section">${sectionHead('CHOOSE YOUR MODE','What would help right now?','No rigid daily schedule. Choose the kind of work you need.')}<div class="entry-grid">${[
 ['01','Understand something','#curriculum','Clear explanations, worked examples, and a question to check your thinking.'],['02','Get a little sharper','#drills','New numbers, thoughtful hints, and honest records of independent attempts.'],['03','Remember it later','#review','Return to attempted skills after a delay and find out what stayed with you.'],['04','Reconnect with the why','#purpose','See how quiet, careful work becomes the ability to build things that matter.']
 ].map(([n,t,url,p])=>`<a class="entry-card" href="${url}"><span class="entry-symbol">${n}</span><h3>${t}</h3><p>${p}</p><span class="entry-arrow">↗</span></a>`).join('')}</div></section>
 <section class="section purpose-feature"><div class="purpose-formula" aria-hidden="true"><span>THE SAME HABIT. A BIGGER HORIZON.</span><b>3/4</b><i>→</i><b>Δv</b><small>understand · calculate · check · explain</small></div><div><div class="eyebrow">THE WORK BEFORE THE BREAKTHROUGH</div><h2>The small work<br>is already the real work.</h2><p>A fraction will not build a spacecraft by itself. But being able to explain it, check it, and notice a wrong answer is the beginning of a capability you will use for years.</p><a class="btn" href="#purpose">Find meaning in the fundamentals →</a></div></section>
 <section class="section">${sectionHead('YOUR MATHEMATICS, IN THE WORLD','Follow a thread into engineering.','These are connections to explore, not specialties you must choose now.')}<div class="capability-tiles">${capabilityPaths.map(p=>`<a href="#map/${p.id}"><span>${p.symbol}</span><small>${p.tag}</small><h3>${p.title}</h3><b>Explore the connection ↗</b></a>`).join('')}</div></section>
 <section class="section discover-strip"><a href="#history"><span>01 / LOOK BACK</span><h3>People invented these ideas for a reason.</h3><p>Explore the problems, cultures, and discoveries behind the symbols.</p></a><a href="#habits"><span>02 / THINK CLEARLY</span><h3>Practise engineering judgment early.</h3><p>Units, assumptions, estimates, evidence, and clear explanations.</p></a><a href="#library"><span>03 / BUILD YOUR STACK</span><h3>One good book. A lot of good work.</h3><p>Find the right free textbook, practice platform, and explanation.</p></a></section>`;
}

export function curriculumPage(state,arg){const selected=stages.some(s=>s.id===arg)?arg:'';return `${intro('THE GUIDED CURRICULUM','Build understanding.<br><em>One useful idea at a time.</em>','A connected foundations map with original explanations and examples. Work beside a textbook and a full practice sequence; use this guide to understand, connect, and revisit.')}<div class="curriculum-note"><b>Start where the reasoning becomes unreliable.</b><p>Arithmetic through Algebra II prepares you to enter precalculus. The final stage is a preview of precalculus itself. You can skip familiar lessons after a fresh check; no need to restart everything.</p><a href="#diagnostic">Try the informal starting-point check →</a></div>${stageTabs('curriculum',selected)}<div class="curriculum-index">${stages.filter(s=>!selected||s.id===selected).map((s)=>{const ls=lessons.filter(l=>l.stage===s.id);return `<section class="curriculum-stage"><header><span class="stage-ordinal">${s.n}</span><div><small>${e(s.tag)}</small><h2>${e(s.title)}</h2><p>${e(s.idea)}</p><span class="read-count">${countRead(state,'lessons',ls)} / ${ls.length} marked read</span></div></header><div class="lesson-list">${ls.map((l,i)=>`<a class="lesson-row" href="${lessonLink(l)}"><span class="lesson-number">${number(i+1)}</span><div><h3>${e(l.title)}</h3><p>${e(l.subtitle)}</p></div><span class="lesson-status" aria-label="${state.lessons?.[l.id]?.read?'Marked read':'Not marked read'}">${state.lessons?.[l.id]?.read?'✓':'↗'}</span></a>`).join('')}</div><div class="stage-bottom"><a href="#drills/${s.id}">Practise ${e(s.title)} →</a><a href="#path/${s.id}">Readiness & resources →</a></div></section>`;}).join('')}</div>`;}

export function lessonPage(state,id){const l=lessons.find(x=>x.id===id);if(!l)return `${intro('LESSON NOT FOUND','Let’s find the right page.','This lesson link is no longer available. Your saved progress is still here.')}<a class="btn primary" href="#curriculum">Open the curriculum →</a>`;const ix=lessons.indexOf(l),record=state.lessons[l.id]||{},q=l.quiz;return `<div class="reader-breadcrumb"><a href="#curriculum/${l.stage}">${e(stageName(l.stage))}</a><span> / LESSON ${number(l.order)}</span></div><header class="lesson-hero"><div class="eyebrow">UNDERSTAND → WORK → CHECK → CONNECT</div><h1>${e(l.title)}</h1><p>${e(l.subtitle)}</p></header><div class="reading-layout"><aside class="reader-rail"><div class="eyebrow">IN THIS LESSON</div><a href="#lesson/${l.id}" data-scroll="lesson-idea">The idea</a><a href="#lesson/${l.id}" data-scroll="lesson-examples">Worked examples</a><a href="#lesson/${l.id}" data-scroll="lesson-quiz">Check understanding</a><a href="#lesson/${l.id}" data-scroll="lesson-engineering">The engineering connection</a><hr><small>BUILD ON</small>${l.prerequisites.length?l.prerequisites.map(id=>{const p=lessons.find(x=>x.id===id);return p?`<a href="${lessonLink(p)}">${e(p.title)}</a>`:'';}).join(''):'<p>No earlier lesson required.</p>'}<hr><a href="#drills/${l.stage}">Open fresh practice ↗</a>${readTools()}</aside><article class="reading-paper"><section id="lesson-idea"><div class="reading-lead">${e(l.why)}</div>${paras(l.explanation)}</section><section id="lesson-examples"><h2>Make it concrete.</h2>${l.worked.map((w,i)=>`<div class="lesson-example"><span class="eyebrow">WORKED EXAMPLE ${i+1}</span><h3>${e(w.title)}</h3><p class="example-given">${e(w.given)}</p><details ${i===0?'open':''}><summary>Walk through the reasoning</summary><ol>${w.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><div class="example-answer">${e(w.answer)}</div><p class="example-check"><b>Check:</b> ${e(w.check)}</p></details></div>`).join('')}</section><section><h2>Watch the reasoning.</h2><ul>${l.pitfalls.map(p=>`<li>${e(p)}</li>`).join('')}</ul></section><section class="lesson-quiz" id="lesson-quiz"><div class="eyebrow">A SMALL CHECK · NOT A PLACEMENT TEST</div><h2>${e(q.prompt)}</h2><form data-lesson-quiz="${l.id}"><fieldset><legend class="sr-only">Choose an answer</legend>${q.options.map(o=>`<label class="quiz-choice"><input type="radio" name="lesson-answer" value="${o.id}" ${record.quizChoice===o.id?'checked':''}><span>${e(o.text)}</span></label>`).join('')}</fieldset><button class="btn primary" type="submit">Check my reasoning →</button><div data-quiz-feedback role="status">${record.quizAttempts?`<p class="quiz-feedback ${record.quizCorrect?'correct':''}">${record.quizCorrect?'Your last answer was correct.':'Revisit the explanation and try again.'} ${e(q.explanation)}</p>`:''}</div></form></section><section id="lesson-engineering" class="engineering-connection"><div class="eyebrow">THE ENGINEERING CONNECTION</div><h2>Where this way of thinking travels.</h2><p>${e(l.engineering)}</p></section><section class="reflection-box"><h3>Explain it without the page.</h3><p>${e(l.reflection)}</p>${noteLink(l.title)}</section>${sourceLinks(l.sources)}<div class="lesson-finish"><button class="btn primary" data-mark-lesson="${l.id}" aria-pressed="${!!record.read}">${record.read?'✓ Marked read · undo':'Mark this lesson read'}</button><a class="btn" href="#drills/${l.stage}">Try fresh problems →</a><small>A read mark records your visit. Independent, delayed work gives better evidence of understanding.</small></div></article></div><nav class="reader-next" aria-label="Adjacent lessons">${ix>0?`<a href="${lessonLink(lessons[ix-1])}"><small>← PREVIOUS</small>${e(lessons[ix-1].title)}</a>`:'<span></span>'}${ix<lessons.length-1?`<a href="${lessonLink(lessons[ix+1])}"><small>NEXT →</small>${e(lessons[ix+1].title)}</a>`:'<a href="#horizon"><small>NEXT →</small>Connect to the college journey</a>'}</nav>`;}

const categories={meaning:'Purpose & identity',learning:'Learn with understanding',practice:'Practise with intention',resilience:'Keep going sustainably'};
function articleBody(a,state,route){return `<article class="reading-paper manual-article"><header><div class="eyebrow">${e(categories[a.category]||'ENGINEERING HABIT')}</div><h1>${e(a.title)}</h1><p class="article-subtitle">${e(a.subtitle)}</p>${readTools()}</header><div class="reading-lead">${e(a.lead)}</div>${a.sections.map(s=>`<section><h2>${e(s.title)}</h2>${paras(s.body)}</section>`).join('')}<section class="reflection-box"><div class="eyebrow">TRY THIS FOR YOURSELF</div><p>${e(a.exercise)}</p>${noteLink(a.title)}</section><div class="article-takeaway"><small>TAKE THIS WITH YOU</small><p>${e(a.takeaway)}</p></div>${sourceLinks(a.sources)}<div class="lesson-finish"><button class="btn" data-mark-article="${a.id}" aria-pressed="${!!state.articles[a.id]?.read}">${state.articles[a.id]?.read?'✓ Marked read · undo':'Mark this guide read'}</button><a href="#${route}" class="text-link">Back to all guides →</a></div></article>`;}
export function manualPage(state,route,arg){const items=route==='habits'?engineeringHabits:route==='purpose'?studyGuides.filter(a=>a.category==='meaning'):studyGuides;const a=items.find(a=>a.id===arg);if(a)return `<div class="reader-breadcrumb"><a href="#${route}">← ${route==='habits'?'Engineering habits':route==='purpose'?'Why the work matters':'Study field manual'}</a></div><div class="reading-layout manual-layout"><aside class="reader-rail"><div class="eyebrow">KEEP EXPLORING</div>${items.filter(x=>x.id!==a.id).slice(0,8).map(x=>`<a href="#${route}/${x.id}">${e(x.title)}</a>`).join('')}<hr><a href="#curriculum">Return to the mathematics →</a></aside>${articleBody(a,state,route)}</div>`;
 const title=route==='purpose'?'Fall in love with<br><em>what the work makes possible.</em>':route==='habits'?'Learn to trust<br><em>your own reasoning.</em>':'A field manual<br><em>for learning difficult things.</em>';
 const desc=route==='purpose'?'You do not need to enjoy every repetitive minute. You can learn to value the clarity, confidence, and useful capability that careful practice creates.':route==='habits'?'Start practising the habits of good engineering before the equations become advanced. Make your thinking inspectable, your assumptions visible, and your conclusions proportionate to the evidence.':'Practical guidance for reading, practice, feedback, help, and returning after an interruption. These are tools to adapt, not a productivity system to obey.';
 const selected=Object.hasOwn(categories,arg)&&route==='study'?arg:'';
 return `${intro(route==='habits'?'THE ENGINEER’S WAY OF THINKING':route==='purpose'?'WHY THE FOUNDATIONS MATTER':'THE STUDY FIELD MANUAL',title,desc)}${route==='purpose'?`<div class="purpose-manifesto"><span>01 → 10 → 100 → 1,000</span><h2>Repetition becomes valuable<br>when something changes.</h2><p>A clearer explanation. A better check. An error you no longer repeat. Look for evidence of growing capability, rather than a perfect mood.</p></div>`:''}${route==='study'?`<div class="stage-tabs"><a href="#study" class="${!selected?'active':''}">All guides</a>${Object.entries(categories).map(([id,t])=>`<a href="#study/${id}" class="${selected===id?'active':''}">${t}</a>`).join('')}</div>`:''}<div class="manual-grid">${items.filter(x=>!selected||x.category===selected).map((a,i)=>`<a href="#${route}/${a.id}" class="manual-card"><span class="manual-number">${number(i+1)}</span><small>${e(categories[a.category]||'ENGINEERING HABIT')}</small><h2>${e(a.title)}</h2><p>${e(a.subtitle)}</p><span class="manual-card-bottom">${state.articles[a.id]?.read?'✓ MARKED READ':'OPEN THE FIELD NOTE'} <b>↗</b></span></a>`).join('')}</div>${route==='purpose'?`<section class="section principles-grid">${launchPrinciples.map(p=>`<article><h3>${e(p.title)}</h3><p>${e(p.text)}</p></article>`).join('')}</section>`:''}`;}

export function projectsPage(state,arg){const p=projects.find(p=>p.id===arg);if(p)return `<div class="reader-breadcrumb"><a href="#projects">← Small engineering projects</a></div><div class="project-brief"><aside><div class="eyebrow">${e(stageName(p.stage))}</div><h1>${e(p.title)}</h1><p>${e(p.goal)}</p><div class="project-materials"><h3>What you need</h3><ul>${p.materials.map(s=>`<li>${e(s)}</li>`).join('')}</ul></div><a href="#curriculum/${p.stage}">Explore the related mathematics →</a></aside><article class="reading-paper"><div class="eyebrow">A SMALL INVESTIGATION</div><h2>Make something you can explain.</h2><ol class="project-steps">${p.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><section><h3>The mathematics</h3><p>${e(p.math)}</p></section><section class="reflection-box"><h3>Keep this as evidence of your work</h3><p>${e(p.deliverable)}</p>${noteLink(p.title)}</section><section><h3>Check your result</h3><p>${e(p.check)}</p><h3>Take it further</h3><p>${e(p.extension)}</p></section><div class="note"><b>What this model leaves out</b><p>${e(p.limits)}</p></div>${sourceLinks(p.sources)}<button class="btn primary" data-mark-project="${p.id}" aria-pressed="${!!state.projects[p.id]?.read}">${state.projects[p.id]?.read?'✓ Marked attempted · undo':'Mark as attempted'}</button></article></div>`;return `${intro('THE SMALL PROJECT STUDIO','Turn a calculation<br><em>into something you can show.</em>','Low-cost investigations with a question, a model, a check, and a tangible record. They are optional ways to make the foundations useful, not substitutes for your classes.')}<div class="project-grid">${projects.map((p,i)=>`<a href="#projects/${p.id}" class="project-card"><div class="project-card-visual"><span>${number(i+1)}</span><i>${['↗','△','≈','◌'][i%4]}</i><small>${e(stageName(p.stage))}</small></div><div><small>${e(p.tier)}</small><h2>${e(p.title)}</h2><p>${e(p.goal)}</p><b>${state.projects[p.id]?.read?'✓ ATTEMPTED':'OPEN THE PROJECT'} →</b></div></a>`).join('')}</div>`;}

export function capabilityPage(arg){const p=capabilityPaths.find(x=>x.id===arg)||capabilityPaths[0];return `${intro('FROM TODAY’S WORK TO TOMORROW’S SYSTEMS','Follow the mathematics<br><em>toward your horizon.</em>','An aerospace degree joins mathematics with physics, computing, design, experiments, and teamwork. Explore how a small foundation becomes part of a much larger capability.')}<div class="capability-selector">${capabilityPaths.map(x=>`<a href="#map/${x.id}" class="${x.id===p.id?'active':''}" ${x.id===p.id?'aria-current="page"':''}><span>${x.symbol}</span>${e(x.tag)}</a>`).join('')}</div><section class="capability-story"><header><div class="eyebrow">${p.tag}</div><h2>${e(p.title)}</h2><p>${e(p.question)}</p><span aria-hidden="true">${p.symbol}</span></header><div class="capability-ladder">${[['01','NOW · FOUNDATIONS',p.now],['02','THE COLLEGE BRIDGE',p.bridge],['03','THE PROFESSIONAL CAPABILITY',p.later]].map(([n,t,text])=>`<article><b>${n}</b><div><small>${t}</small><p>${e(text)}</p></div></article>`).join('')}</div><div class="capability-example"><div><small>A SMALL MODEL YOU CAN UNDERSTAND NOW</small><p>${e(p.example)}</p></div><div><small>EXPLAIN THE REASONING</small><p>${e(p.prompt)}</p></div></div><div class="actions"><a class="btn primary" href="#curriculum/${p.stage}">Build this foundation →</a><a class="btn" href="#labs/${p.lab}">Explore the interactive lab ↗</a></div>${sourceLinks([p.source])}</section><section class="section">${sectionHead('CONNECT THE SELF-STUDY TO COLLEGE','Keep the official plan in view.','Your tentative Southwestern start and longer-term aerospace goal give direction. Official placement, major preparation, and current transfer agreements determine enrollment.')}<div class="college-link-grid">${collegeLinks.map(s=>`<article><h3>${link(s.url,s.title)}</h3><p>${e(s.detail)}</p></article>`).join('')}</div><p class="smallprint">A 2033 graduation target is a planning assumption, not a guaranteed schedule. Building strong foundations is useful across aerospace specialties; you can choose a narrow focus later.</p></section>`;}

export function progressPage(state){const records=Object.values(state.drills?.records||{}),attempts=records.reduce((n,r)=>n+r.attempts,0),independent=records.reduce((n,r)=>n+r.independentCorrect,0),assisted=records.reduce((n,r)=>n+r.assistedCorrect,0),due=getDrillReview(state.drills).filter(r=>r.due).length;return `${intro('YOUR LEARNING RECORD','Keep evidence.<br><em>Notice what is changing.</em>','This is a record of activity in this browser, not a grade or a prediction of engineering ability. Look for explanations you can give and problems you can solve after a delay.')}<div class="progress-metrics">${[[countRead(state,'lessons',lessons),'lessons marked read'],[attempts,'first attempts recorded'],[independent,'independent first-attempt answers correct'],[assisted,'helped first-attempt answers correct']].map(([n,t])=>`<div><b>${n}</b><span>${t}</span></div>`).join('')}</div><section class="progress-layout"><article class="progress-panel"><h2>Your foundation map.</h2><p>Read marks show coverage. They do not establish mastery.</p>${stages.map(s=>{const ls=lessons.filter(l=>l.stage===s.id),n=countRead(state,'lessons',ls),rs=skills.filter(x=>x.stage===s.id&&state.drills?.records?.[x.id]?.attempts).length;return `<a class="stage-progress" href="#curriculum/${s.id}"><div><b>${e(s.title)}</b><span>${n}/${ls.length} read · ${rs}/6 practice skills attempted</span></div><progress value="${n}" max="${ls.length}" aria-label="${e(s.title)} lessons marked read">${n}</progress></a>`;}).join('')}</article><aside class="progress-panel"><div class="eyebrow">THE NEXT CHECK</div><h2>${due?`${due} skills to revisit.`:'Make room for remembering.'}</h2><p>Review suggestions come from your recorded first attempts. The intervals are a simple study heuristic, not a validated mastery model.</p><a class="btn primary" href="#review">Open the review queue →</a><hr><p><b>${state.notes.length}</b> notes · <b>${state.saved.length}</b> saved resources · <b>${countRead(state,'projects',projects)}</b> projects marked attempted</p><a href="#notebook">Open your notebook →</a></aside></section><section class="section backup-panel"><div><div class="eyebrow">KEEP YOUR WORK PORTABLE</div><h2>Your progress belongs with you.</h2><p>Notes and records stay in this browser. Export a backup periodically, especially before changing devices or clearing browser data. Imports merge by record; they never add duplicate practice counters.</p><p class="smallprint">Backups contain your personal notes. Store them somewhere you trust. There is no account or cloud sync.</p></div><div class="backup-controls"><button class="btn primary" data-backup>Download my backup ↓</button><label class="backup-label" for="backup-file">Restore from a Math Prep JSON backup</label><input id="backup-file" type="file" accept=".json,application/json"><div id="backup-preview" role="status"></div></div></section><section class="section principles-grid">${launchPrinciples.map(p=>`<article><h3>${e(p.title)}</h3><p>${e(p.text)}</p></article>`).join('')}</section>`;}

export function buildSearchIndex(){return [
 ...lessons.map(x=>({title:x.title,kind:'Lesson',text:[x.subtitle,x.why,...x.explanation].join(' '),url:lessonLink(x)})),
 ...studyGuides.map(x=>({title:x.title,kind:'Study guide',text:x.subtitle+' '+x.lead,url:'#study/'+x.id})),
 ...engineeringHabits.map(x=>({title:x.title,kind:'Engineering habit',text:x.subtitle+' '+x.lead,url:'#habits/'+x.id})),
 ...projects.map(x=>({title:x.title,kind:'Project',text:x.goal+' '+x.math,url:'#projects/'+x.id})),
 ...resources.map(x=>({title:x.title,kind:'Resource',text:x.desc+' '+x.role,url:'#library/'+(x.levels[0]==='all'?'':x.levels[0])})),
 ...concepts.map(x=>({title:x.title,kind:'Concept',text:JSON.stringify(x),url:'#concepts/'+x.stage})),
 ...historyEntries.map(x=>({title:x.title,kind:'History',text:JSON.stringify(x),url:'#history/'+x.id})),
 ...missions.map(x=>({title:x.title,kind:'Aerospace example',text:JSON.stringify(x),url:'#missions/'+x.id})),
 ...skills.map(x=>({title:x.title,kind:'Practice skill',text:x.description+' '+x.stage,url:'#drills/'+x.id}))
 ];}
export function searchPage(arg=''){return `${intro('SEARCH YOUR FIELD ATLAS','Find the next useful idea.','Search lessons, guides, projects, resources, history, and practice skills. Try a topic, a difficulty, or something you want to build.')}<form id="platform-search-form" class="platform-search"><label for="platform-search" class="sr-only">Search the learning platform</label><input id="platform-search" type="search" placeholder="Try fractions, units, robots, or getting stuck…" value="${e(arg)}" autocomplete="off"><button class="btn primary">Search →</button></form><div id="search-summary" role="status"></div><div id="platform-results"></div>`;}
export function platformSources(){const all=[...fieldManualSources,...collegeLinks,...capabilityPaths.map(x=>x.source),...lessons.flatMap(x=>x.sources)];const unique=[...new Map(all.map(s=>[s.url,s])).values()];return `<section class="section"><div class="eyebrow">EXPANDED CURRICULUM & FIELD MANUAL</div><h2>Follow the ideas to their sources.</h2><p class="source-explainer">Lessons and hypothetical projects are original teaching material. Sources supply further reading and support underlying concepts; study routines and review intervals are editorial suggestions. Engineering models here simplify real systems and are not design specifications.</p><details class="expanded-sources"><summary>Browse ${unique.length} curriculum, study, and engineering references</summary>${unique.map(s=>`<p>${link(s.url,s.title)}</p>`).join('')}</details><p class="smallprint">Hero photograph: NASA, Earth viewed through the ISS Cupola. ${link('https://svs.gsfc.nasa.gov/webapps/planet-pen/Images/Cupola/','Original image collection')}. NASA does not endorse this site.</p></section>`;}

export function mountPlatform(root,{state,view,arg,onSave,refresh,toast,validators}){
 const controller=new AbortController(),signal=controller.signal;
 const listen=(el,event,fn)=>el?.addEventListener(event,fn,{signal});
 const save=()=>{onSave();};
 if(view==='lesson'&&lessons.some(l=>l.id===arg)){state.lastLesson=arg;save();}
 listen(root,'click',event=>{const button=event.target.closest('button,a');if(!button)return;
  if(button.hasAttribute('data-scroll')){event.preventDefault();root.querySelector('#'+button.dataset.scroll)?.scrollIntoView({behavior:'auto',block:'start'});}
  if(button.hasAttribute('data-reading')){state.preferences.reading=state.preferences.reading==='large'?'comfortable':'large';document.documentElement.dataset.reading=state.preferences.reading;save();toast(state.preferences.reading==='large'?'Larger reading text enabled.':'Comfortable reading text enabled.');}
  if(button.hasAttribute('data-print'))window.print();
  for(const [attr,key,label]of [['markLesson','lessons','read'],['markArticle','articles','read'],['markProject','projects','attempted']])if(button.dataset[attr]){const id=button.dataset[attr],old=state[key][id]||{},read=!old.read;state[key][id]={...old,read,date:new Date().toISOString()};save();button.setAttribute('aria-pressed',String(read));button.textContent=read?`✓ Marked ${label} · undo`:label==='attempted'?'Mark as attempted':key==='lessons'?'Mark this lesson read':'Mark this guide read';}
  if(button.hasAttribute('data-backup'))downloadBackup(state);
 });
 const form=root.querySelector('[data-lesson-quiz]');listen(form,'submit',event=>{event.preventDefault();const l=lessons.find(x=>x.id===form.dataset.lessonQuiz),choice=new FormData(form).get('lesson-answer'),out=form.querySelector('[data-quiz-feedback]');if(!choice){out.textContent='Choose an answer before checking.';return;}const correct=choice===l.quiz.answer,old=state.lessons[l.id]||{};state.lessons[l.id]={...old,quizChoice:choice,quizCorrect:correct,quizAttempts:(old.quizAttempts||0)+1,date:new Date().toISOString()};save();out.innerHTML=`<p class="quiz-feedback ${correct?'correct':''}"><b>${correct?'Correct.':'Not quite yet.'}</b> ${e(l.quiz.explanation)}</p>`;});
 let incoming=null,selection=0;listen(root.querySelector('#backup-file'),'change',async event=>{const selected=++selection;const file=event.target.files[0],out=root.querySelector('#backup-preview');incoming=null;if(!file)return;try{if(file.size>50000000)throw new Error('Choose a backup smaller than 50 MB.');const text=await file.text();if(selected!==selection||signal.aborted)return;incoming=parseBackup(text,validators);out.innerHTML=`<p>Ready to merge ${incoming.notes.length} notes, ${incoming.saved.length} saved resources, and ${Object.keys(incoming.lessons).length} lesson records. Newer activity records replace older records for the same skill or lesson; their counters are not added. Existing notes with the same ID stay unchanged.</p><button class="btn" id="confirm-backup">Merge this backup</button>`;listen(out.querySelector('#confirm-backup'),'click',()=>{if(!incoming)return;try{Object.assign(state,mergeWorkspace(state,incoming));save();refresh();toast('Backup merged. Newer activity records retained; counters were not added.');}catch(error){if(selected===selection&&!signal.aborted)out.textContent=error.message;}});}catch(error){if(selected===selection&&!signal.aborted)out.textContent=error.message;}});
 if(view==='search'){const index=buildSearchIndex(),input=root.querySelector('#platform-search'),out=root.querySelector('#platform-results'),summary=root.querySelector('#search-summary');const update=()=>{const q=input.value.trim().toLowerCase(),words=q.split(/\s+/).filter(Boolean);const hits=words.length?index.filter(x=>words.every(w=>(x.title+' '+x.text).toLowerCase().includes(w))):[];summary.textContent=q?`${hits.length} results for “${input.value.trim()}”`:'Start with a topic or question. Your private notes are not included in search.';out.innerHTML=hits.length?hits.slice(0,80).map(x=>`<a class="search-result" href="${e(x.url)}"><small>${e(x.kind)}</small><h2>${e(x.title)}</h2><span>Open →</span></a>`).join(''):q?'<div class="empty"><h2>No matching pages yet.</h2><p>Try one broad word: fraction, graph, practice, or units.</p></div>':'';};listen(input,'input',update);listen(root.querySelector('#platform-search-form'),'submit',event=>{event.preventDefault();update();});update();}
 return ()=>{selection++;controller.abort();};
}
